package com.nextrade.domain.portfolio; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; import java.math.*;
public final class Holding {private final InstrumentId instrumentId;private Quantity quantity;private Quantity reserved;private Price averagePrice;public Holding(InstrumentId id){instrumentId=id;quantity=Quantity.zero();reserved=Quantity.zero();}public void buy(Quantity q,Price p){BigDecimal old=averagePrice==null?BigDecimal.ZERO:averagePrice.value().multiply(quantity.value());BigDecimal total=quantity.value().add(q.value());averagePrice=new Price(old.add(p.value().multiply(q.value())).divide(total,8,RoundingMode.HALF_EVEN),p.tickSize());quantity=quantity.add(q);}public void sell(Quantity q){if(available().compareTo(q)<0)throw new IllegalArgumentException("Insufficient position");quantity=quantity.subtract(q);}public void reserve(Quantity q){if(available().compareTo(q)<0)throw new IllegalArgumentException("Insufficient position");reserved=reserved.add(q);}public void release(Quantity q){reserved=reserved.subtract(q);}public Quantity available(){return quantity.subtract(reserved);}public InstrumentId instrumentId(){return instrumentId;}public Quantity quantity(){return quantity;}public Quantity reserved(){return reserved;}public Price averagePrice(){return averagePrice;}}
